<x-filament-panels::page>
 @php($health=$this->health())
 <section class="bc-admin-hero"><div><span class="bc-admin-eyebrow">OPERATIONS</span><h2>Everything running, in one view.</h2><p>Live service checks, queue backlog and workspace storage.</p></div><span class="bc-admin-status">{{ ucfirst($health['status']) }}</span></section>
 <div class="bc-admin-grid">@foreach($health['checks'] as $name=>$status)<div class="bc-admin-card"><span class="bc-admin-eyebrow">{{ $name }}</span><h3>{{ str_starts_with($status,'ok') ? 'Operational' : 'Needs attention' }}</h3><p>{{ $status }}</p></div>@endforeach</div>
 <x-filament::section heading="Queue backlog"><div class="bc-admin-grid">@foreach($this->queues() as $name=>$count)<div><span>{{ $name }}</span><h3>{{ $count }}</h3></div>@endforeach</div></x-filament::section>
 <x-filament::section heading="Storage by workspace and kind"><div class="bc-admin-table-wrap"><table class="bc-admin-table"><thead><tr><th>Workspace</th><th>Kind</th><th>Files</th><th>Storage</th><th>Workspace quota</th></tr></thead><tbody>@forelse($this->storage() as $r)<tr><td>{{ $r['name'] }}</td><td>{{ $r['kind'] }}</td><td>{{ number_format($r['files']) }}</td><td>{{ number_format($r['bytes']/1048576,2) }} MB</td><td>{{ $r['quota'] ? $r['quota'].' GB · '.$r['percent'].'%' : 'Unlimited' }} @if($r['percent'] >= 80)<strong> · Quota warning</strong>@endif</td></tr>@empty<tr><td colspan="5">No uploads yet</td></tr>@endforelse</tbody></table></div></x-filament::section>
 <div class="bc-admin-grid-two"><x-filament::section heading="Largest 100 attachments"><div class="bc-admin-scroll">@forelse($this->largest() as $a)<div class="bc-admin-row"><span>{{ $a->original_name }}</span><strong>{{ number_format($a->size_bytes/1048576,2) }} MB</strong></div>@empty<p>No attachments</p>@endforelse</div></x-filament::section><x-filament::section heading="Recent failed jobs"><div class="bc-admin-scroll">@forelse($this->failures() as $f)<div class="bc-admin-row"><strong>{{ $f->queue }}</strong><time>{{ $f->failed_at }}</time><small>{{ $f->uuid }}</small></div>@empty<p>No failed jobs</p>@endforelse</div></x-filament::section></div>
</x-filament-panels::page>
